package app

// Config holds server settings.
type Config struct {
	Port int
	Name string
}

// Default returns the default Config.
func Default() Config {
	return Config{Port: 8080, Name: "app"}
}

package app

// Boot wires the app from the default configuration.
func Boot() string {
	c := Default()
	s := NewServer(c)
	return s.Addr() + " " + Describe(c)
}

package app

// Describe returns a one-line description of a Config.
func Describe(c Config) string {
	return c.Name
}

package app

import "fmt"

// Server serves requests.
type Server struct {
	cfg Config
}

// NewServer builds a Server from a Config.
func NewServer(c Config) *Server {
	return &Server{cfg: c}
}

func (s *Server) Addr() string {
	return fmt.Sprintf(":%d", s.cfg.Port)
}

package app

import "testing"

func TestBoot(t *testing.T) {
	if got := Boot(); got != ":8080 app" {
		t.Fatalf("Boot() = %q, want \":8080 app\"", got)
	}
	var c Config = Default()
	if c.Port != 8080 {
		t.Fatalf("Port = %d", c.Port)
	}
}

